package net.civeira.phylax.features.notification.message.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class ContentVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property content of message ")
  void test_content_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> ContentVO.tryFrom(null));
    Assertions.assertEquals("one", ContentVO.from("one").getContent());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> ContentVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", ContentVO.from("one").toString());
  }
}
